namespace StarlightSyndicateDemo;
public static class InformationTests
{
 public static void Run(){int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception("INFORMATION FAIL: "+label);checks++;}var catalog=InformationCatalog.ByKey;
 foreach(var item in ItemCatalog.All.DistinctBy(i=>i.Id))Check(catalog.ContainsKey(InformationCatalog.ItemKey(item.Id)),"Every inventory/market type has information: "+item.Id);
 foreach(var hull in FleetCatalog.All){var e=catalog[InformationCatalog.ItemKey(hull.Id)];Check(e.Kind=="Ship"&&e.Tabs.ContainsKey("Fitting")&&e.Tabs.ContainsKey("Source"),"Ship tabs and source fields: "+hull.Id);Check(e.Stats.Count>=hull.Attributes.Count,"All recorded hull attributes: "+hull.Id);Check(!hull.Playable?e.MarketId.Length==0:true,"Reference hull cannot acquire market actions: "+hull.Id);}
 foreach(var s in DemoWorld.Systems){var e=catalog["system/"+s.Id];Check(e.Tabs.ContainsKey("Orbital Bodies")&&e.Tabs.ContainsKey("Stations")&&e.Tabs.ContainsKey("Structures")&&e.Tabs.ContainsKey("Route"),"Solar system contextual tabs: "+s.Id);Check(e.Tabs["Neighbors"].Count==s.Links.Length,"System connections are real: "+s.Id);Check(catalog.ContainsKey("region/"+s.Region)&&catalog.ContainsKey("faction/"+s.Faction),"Region and sovereignty links: "+s.Id);}
 foreach(var celestial in SolarCatalog.ById.Values)Check(catalog.ContainsKey("celestial/"+celestial.Id),"Every charted celestial has info: "+celestial.Id);
 foreach(var e in catalog.Values){Check(e.Key.Length>0&&e.Name.Length>0&&e.Group.Length>0&&e.Tabs.Count>0,"Valid record: "+e.Key);foreach(var link in e.Tabs.Values.SelectMany(r=>r).Where(r=>r.Link.Length>0))Check(catalog.ContainsKey(link.Link)||(link.Link.StartsWith("item/")&&UnifiedCatalog40.Source(link.Link[5..])!=null),"Resolved crosslink: "+link.Link);foreach(var key in e.Related)Check(catalog.ContainsKey(key),"Resolved variation: "+key);}
 foreach(var module in MobilityCatalog.All){var e=catalog[InformationCatalog.ItemKey(module.Id)];Check(e.Tabs["Fitting"].Any(r=>r.Label=="CPU"&&r.Value==InformationCatalog.Format("Cpu",module.Cpu)),"CPU uses actual module data");Check(e.Tabs["Fitting"].Any(r=>r.Label=="Power"&&r.Value==InformationCatalog.Format("Power",module.Power)),"Power uses actual module data");}
 var weapon=WeaponCatalog.All.First(w=>ChargeCatalog.For(w).Length>0);var weaponInfo=catalog[InformationCatalog.ItemKey(weapon.Id)];Check(weaponInfo.Tabs["Used With"].Count==ChargeCatalog.For(weapon).Length,"Weapon charge compatibility matches simulation");
 Check(catalog.Values.Any(e=>e.Kind=="Drone"&&e.Tabs.GetValueOrDefault("Details")?.Any(r=>r.Label.StartsWith("Packet"))==true),"Drone damage packets exposed");Check(catalog.Values.Any(e=>e.Kind=="Module"&&e.Tabs.GetValueOrDefault("Details")?.Any(r=>r.Label.StartsWith("Modifiers"))==true),"Rig modifier definitions exposed");
 var region=catalog["region/Aster Reach"];Check(region.Tabs["Solar Systems"].Count==DemoWorld.Systems.Count(s=>s.Region=="Aster Reach"),"Region lists only its actual systems");
 Console.WriteLine($"{checks} information catalog checks passed / {catalog.Count} records / {catalog.Values.Sum(e=>e.Tabs.Values.Sum(t=>t.Count))} information rows.");}
}
